def run_horizon_prefilter(image_dir, output_dir, prefilter,
                          confidence_threshold=0.45,
                          extensions=('.jpg','.jpeg','.png')):
    os.makedirs(output_dir, exist_ok=True)
    files = sorted(f for f in os.listdir(image_dir) if f.lower().endswith(extensions))
    passed = 0
    for fname in tqdm(files, desc="Horizon filter"):
        img = cv2.imread(os.path.join(image_dir, fname))
        if img is None: continue
        is_h, conf = prefilter.predict(img)
        if is_h and conf >= confidence_threshold:
            shutil.copy2(os.path.join(image_dir, fname),
                         os.path.join(output_dir, fname))
            passed += 1
    print(f"{passed}/{len(files)} images passed → {output_dir}")
    return passed

