"""## 3 — Reliability Scoring Functions

### R(p) — Phase Congruency (illumination-invariant stability)
Measures the degree to which Fourier components are in phase at each pixel.
High phase congruency = structure determined by terrain geometry, not albedo.
These features survive the orbital-to-rover illumination transformation.

### H(p) — Spectral Entropy (distinctiveness)
Shannon entropy of the patch's normalised SVD eigenvalue spectrum.
High entropy = variance spread across many directions = distinctive, matchable.

### T(p) — Combined Score
```
T(p) = α·R(p) + β·H(p)
```
Captures the stability–distinctiveness tradeoff explicitly.

"""

# ── Phase congruency (log-Gabor implementation) ──────────────────────────
def compute_rp(patch_gray, n_scale=4, n_orient=6, min_wavelength=3,
               mult=2.1, sigma_on_f=0.55, epsilon=1e-8):
    img = patch_gray.astype(np.float64)
    rows, cols = img.shape
    IMG = np.fft.fft2(img)

    y_idx = np.fft.fftfreq(rows)
    x_idx = np.fft.fftfreq(cols)
    X, Y  = np.meshgrid(x_idx, y_idx)
    radius = np.sqrt(X**2 + Y**2)
    radius[0, 0] = 1
    theta_grid = np.arctan2(-Y, X)

    pc_total = np.zeros((rows, cols))

    for o in range(n_orient):
        angle   = o * np.pi / n_orient
        ds      = np.sin(theta_grid - angle)
        dc      = np.cos(theta_grid - angle)
        d_theta = np.abs(np.arctan2(ds, dc))
        spread  = np.exp(-d_theta**2 / (2 * (np.pi / n_orient)**2))

        sum_e  = np.zeros((rows, cols))
        sum_o  = np.zeros((rows, cols))
        sum_an = np.zeros((rows, cols))

        for s in range(n_scale):
            wavelength = min_wavelength * mult**s
            fo         = 1.0 / wavelength
            log_gabor  = np.exp(-(np.log(radius / fo))**2 /
                                 (2 * np.log(sigma_on_f)**2))
            log_gabor[0, 0] = 0

            filt = IMG * log_gabor * spread
            resp = np.fft.ifft2(filt)
            e    = np.real(resp)
            o_   = np.imag(resp)
            an   = np.sqrt(e**2 + o_**2)

            sum_e  += e
            sum_o  += o_
            sum_an += an

        # Net response / total amplitude (no noise compensation)
        pc = np.sqrt(sum_e**2 + sum_o**2) / (sum_an + epsilon)
        pc_total += pc

    return float(np.mean(pc_total / n_orient))

# ── Spectral entropy (distinctiveness) ───────────────────────────────────
def compute_hp(patch_gray, epsilon=1e-8):
    """Shannon entropy of the normalised SVD eigenvalue spectrum."""
    img = patch_gray.astype(np.float32)
    _, s, _ = np.linalg.svd(img, full_matrices=False)
    p = s / (s.sum() + epsilon)
    return float(-np.sum(p * np.log(p + epsilon)))


# ── Combined T(p) ─────────────────────────────────────────────────────────
def compute_tp(rp, hp, rp_std, hp_std, alpha=0.5, beta=0.5, epsilon=1e-8):
    rp_norm = rp / (rp_std + epsilon)
    hp_norm = hp / (hp_std + epsilon)
    return alpha * rp_norm + beta * hp_norm

print("Scoring functions defined ✓")

"""## 4 — Dense Grid Patch Extraction

We extract patches on a regular grid rather than at SIFT keypoints.
SIFT pre-selects for the same properties R(p) measures, killing dynamic range.
Dense extraction preserves the full distribution of reliability scores.

"""

PATCH_SIZE  = 64    # pixels
GRID_STRIDE = 32    # step between patch centres

def extract_grid_patches(img_gray, img_pil, patch_size=PATCH_SIZE, stride=GRID_STRIDE):
    """
    Returns:
        patches_gray : list of (P,P) float32 arrays in [0,1]
        patches_pil  : list of PIL Images (RGB, for DINOv2)
        centres      : list of (cx, cy)
    """
    H, W   = img_gray.shape
    half   = patch_size // 2
    pg_out, pp_out, ctr_out = [], [], []

    for cy in range(half, H - half, stride):
        for cx in range(half, W - half, stride):
            pg = img_gray[cy-half:cy+half, cx-half:cx+half]
            if pg.shape != (patch_size, patch_size):
                continue
            pr = img_pil.crop((cx-half, cy-half, cx+half, cy+half)).convert('RGB')
            pg_out.append(pg.astype(np.float32) / 255.0)
            pp_out.append(pr)
            ctr_out.append((cx, cy))

    return pg_out, pp_out, ctr_out

print("extract_grid_patches() defined ✓")

