"""##RETROACTICE HORIZON FILTER"""

# ── Retroactive horizon filter ────────────────────────────────────────────────
# Detects horizon presence per image and adds has_horizon flag to df.
# Reads original images from HORIZON_DIR (already filtered set).
# No re-scoring needed.

import cv2
import numpy as np
from pathlib import Path
from tqdm import tqdm

NAVCAM_DIR = '/content/drive/MyDrive/NASA_Mars_Curiosity/NAVCAM'

def has_horizon(img_path, band=(0.15, 0.55), threshold=0.25):
    """
    True if a strong horizontal edge exists in the vertical band
    [band[0]*H : band[1]*H]. Uses horizontal Sobel (dy) to emphasise
    horizon lines rather than vertical terrain texture.
    """
    img = cv2.imread(str(img_path), cv2.IMREAD_GRAYSCALE)
    if img is None:
        return False
    H, W = img.shape
    roi     = img[int(H * band[0]) : int(H * band[1]), :]
    sobel_h = np.abs(cv2.Sobel(roi, cv2.CV_32F, dx=0, dy=1, ksize=3))
    return (sobel_h.mean() / 255.0) > threshold

# ── Score each unique image ───────────────────────────────────────────────────
unique_images = df['image'].unique()
print(f"Checking horizon in {len(unique_images)} images...")

horizon_flags = {}
missing = []
for fname in tqdm(unique_images, desc="Horizon detect"):
    # Images were scored from HORIZON_DIR — try there first, then NAVCAM_DIR
    for search_dir in [HORIZON_DIR, NAVCAM_DIR]:
        p = Path(search_dir) / fname
        if not p.exists():
            p = Path(search_dir) / (Path(fname).stem + '.JPG')
        if p.exists():
            horizon_flags[fname] = has_horizon(p)
            break
    else:
        missing.append(fname)
        horizon_flags[fname] = False

# ── Merge and report ──────────────────────────────────────────────────────────
df['has_horizon'] = df['image'].map(horizon_flags)

n_imgs_kept    = sum(horizon_flags.values())
n_patches_kept = df['has_horizon'].sum()

print(f"\nImages  : {n_imgs_kept}/{len(unique_images)} passed ({100*n_imgs_kept/len(unique_images):.1f}%)")
print(f"Patches : {n_patches_kept:,}/{len(df):,} retained ({100*n_patches_kept/len(df):.1f}%)")
print(f"Missing : {len(missing)}")

df_horizon = df[df['has_horizon']].copy()
