import json
import numpy as np
import glymur
from pathlib import Path

HIRISE_PATH    = '/content/drive/MyDrive/NASA_Mars_Curiosity/Patches/ESP_035350_1755_RED.JP2'
POSITIONS_PATH = '/content/drive/MyDrive/NASA_Mars_Curiosity/navcam_positions.json'

# ── Geotransform from JP2 metadata ───────────────────────────────────────────
ORIGIN_X   = -2526177.875   # upper-left easting  (m)
ORIGIN_Y   = -271190.625    # upper-left northing (m)
PIXEL_SIZE =  0.25          # m/pixel
MARS_R     =  3396190.0     # sphere radius (m)

def latlon_to_hirise_px(lat_deg, lon_deg):
    """
    Mars Equirectangular (standard parallel 0, lon_origin 180°).
    Returns (col, row) — i.e. (x, y) in pixel space.
    """
    # Equirectangular: easting measured from lon_origin=180
    lon_origin = 180.0
    easting  = MARS_R * np.radians(lon_deg - lon_origin)
    northing = MARS_R * np.radians(lat_deg)
    col = (easting  - ORIGIN_X) / PIXEL_SIZE
    row = (ORIGIN_Y - northing) / PIXEL_SIZE   # row increases downward
    return col, row

