# ── Geotransform ──────────────────────────────────────────────────────────────
ORIGIN_X   = -2526177.875
ORIGIN_Y   = -271190.625
PIXEL_SIZE =  0.25
MARS_R     =  3396190.0
LON_ORIGIN =  180.0

def latlon_to_px(lat_deg, lon_deg):
    easting  = MARS_R * np.radians(lon_deg - LON_ORIGIN)
    northing = MARS_R * np.radians(lat_deg)
    col = (easting  - ORIGIN_X) / PIXEL_SIZE
    row = (ORIGIN_Y - northing) / PIXEL_SIZE
    return int(round(col)), int(round(row))

