import pandas as pd
import numpy as np
import rasterio
from rasterio.windows import Window
import matplotlib.pyplot as plt
from pyproj import Transformer

# ── 1. Load rover positions ──────────────────────────────────────────────────
pos = pd.read_csv('localized_pos.csv')
print(pos.columns.tolist())  # confirm column names

# Get one representative position per sol (median to avoid outliers)
sol_positions = (
    pos.groupby('sol')[['planetocentric_latitude', 'longitude']]
    .median()
    .reset_index()
    .rename(columns={'planetocentric_latitude': 'lat', 'longitude': 'lon'})
)

# ── 2. Convert lat/lon to HiRISE JP2 projected coords ───────────────────────
# JP2 CRS: Equirectangular MARS, central meridian 180
# We need to go from geographic (lat/lon on Mars) to projected metres
transformer = Transformer.from_crs(
    "GEOGCRS[\"GCS_MARS\",DATUM[\"unnamed\",ELLIPSOID[\"unnamed\",3396190,0]],CS[ellipsoidal,2],AXIS[\"latitude\",north],AXIS[\"longitude\",east],UNIT[\"degree\",0.0174532925199433]]",
    "PROJCS[\"Equirectangular MARS\",GEOGCS[\"GCS_MARS\",DATUM[\"unnamed\",SPHEROID[\"unnamed\",3396190,0]],PRIMEM[\"Reference meridian\",0],UNIT[\"degree\",0.0174532925199433]],PROJECTION[\"Equirectangular\"],PARAMETER[\"central_meridian\",180],UNIT[\"metre\",1]]",
    always_xy=True
)

sol_positions['x_m'], sol_positions['y_m'] = transformer.transform(
    sol_positions['lon'].values,
    sol_positions['lat'].values
)

# ── 3. Extract HiRISE chip at rover position ─────────────────────────────────
HIRISE_PATH = 'your_file.jp2'
CHIP_SIZE = 256  # pixels (~64m at 0.25m/px)

def get_hirise_chip(x_m, y_m, chip_size=CHIP_SIZE):
    with rasterio.open(HIRISE_PATH) as src:
        row, col = src.index(x_m, y_m)
        half = chip_size // 2
        # Clamp to image bounds
        col_off = max(0, col - half)
        row_off = max(0, row - half)
        window = Window(col_off, row_off, chip_size, chip_size)
        chip = src.read(1, window=window)
    return chip

# ── 4. Side-by-side comparison per sol ──────────────────────────────────────
import cv2, glob, os

def load_navcam_patch(sol, cx, cy, image_name, navcam_dir, patch_size=64):
    """Load a single NavCam patch centered at (cx, cy)."""
    path = glob.glob(os.path.join(navcam_dir, f'*sol{sol:04d}*{image_name[:20]}*.jpg'))
    if not path:
        return None
    img = cv2.imread(path[0], cv2.IMREAD_GRAYSCALE)
    if img is None:
        return None
    half = patch_size // 2
    return img[cy-half:cy+half, cx-half:cx+half]

def compare_sol(sol, df, sol_positions, navcam_dir, n_patches=3):
    """Show HiRISE chip alongside NavCam patches for a given sol."""
    pos_row = sol_positions[sol_positions['sol'] == int(sol)]
    if pos_row.empty:
        print(f"No position data for sol {sol}")
        return

    x_m, y_m = pos_row.iloc[0][['x_m', 'y_m']]
    chip = get_hirise_chip(x_m, y_m)

    sol_patches = df[df['sol'] == sol].nlargest(n_patches, 'rp')  # top rp patches

    fig, axes = plt.subplots(1, n_patches + 1, figsize=(4 * (n_patches + 1), 4))
    axes[0].imshow(chip, cmap='gray')
    axes[0].set_title(f'HiRISE\nSol {sol}')
    axes[0].axis('off')

    for i, (_, row) in enumerate(sol_patches.iterrows()):
        patch = load_navcam_patch(row['sol'], row['cx'], row['cy'],
                                   row['image'], navcam_dir)
        if patch is not None:
            axes[i+1].imshow(patch, cmap='gray')
        axes[i+1].set_title(f"NavCam patch\n({row['cx']},{row['cy']})\nrp={row['rp']:.3f}")
        axes[i+1].axis('off')

    plt.suptitle(f'Sol {sol} — NavCam vs HiRISE', fontsize=13)
    plt.tight_layout()
    plt.show()

# ── 5. Run for a few sols ────────────────────────────────────────────────────
NAVCAM_DIR = '/path/to/navcam/images'

for sol in ['0437', '0453', '0477']:  # pick a few sols to inspect
    compare_sol(sol, df, sol_positions, NAVCAM_DIR)

