import numpy as np

def latlon_to_jp2_coords(lat, lon):
    """
    Convert Mars lat/lon (degrees) to JP2 projected coordinates.
    Equirectangular MARS: central meridian 180, sphere radius 3396190m
    """
    R = 3396190.0  # Mars sphere radius in metres
    lon0 = 180.0   # central meridian

    # Equirectangular projection
    x = R * np.radians(lon - lon0)
    y = R * np.radians(lat)
    return x, y

