band = ds.GetRasterBand(1)
print(f"GDAL opened: {ds.RasterXSize} × {ds.RasterYSize}, "
      f"dtype={gdal.GetDataTypeName(band.DataType)}")

hirise_records = []

for fname, col, row in tqdm(mapping, desc="Extracting HiRISE patches"):
    # GDAL ReadAsArray(xoff, yoff, xsize, ysize)
    window = band.ReadAsArray(col - half, row - half, PATCH_SIZE, PATCH_SIZE)

    if window is None:
        print(f"  WARNING: null read at ({col},{row}) for {fname}")
        continue

    # uint16 → uint8
    w_min, w_max = int(window.min()), int(window.max())
    if w_max > w_min:
        patch_u8 = ((window.astype(np.float32) - w_min) /
                    (w_max - w_min) * 255).astype(np.uint8)
    else:
        patch_u8 = np.zeros((PATCH_SIZE, PATCH_SIZE), dtype=np.uint8)

    pos = pos_by_fname[fname]
