# ── Dual DINOv2 embedding: NAVCAM patches + HiRISE patches ───────────────────
import torch
import numpy as np
import pickle
from PIL import Image
from torchvision import transforms
from tqdm import tqdm

DEVICE = 'cuda' if torch.cuda.is_available() else 'cpu'
print(f"Device: {DEVICE}")

# ── Load DINOv2 ───────────────────────────────────────────────────────────────
model = torch.hub.load('facebookresearch/dinov2', 'dinov2_vits14')
model.eval().to(DEVICE)

# ── Preprocessing ─────────────────────────────────────────────────────────────
preprocess = transforms.Compose([
    transforms.Resize((224, 224)),
    transforms.Grayscale(num_output_channels=3),  # NAVCAM/HiRISE are grayscale
    transforms.ToTensor(),
    transforms.Normalize(mean=[0.485, 0.456, 0.406],
                         std=[0.229, 0.224, 0.225]),
])

def embed_patches(patch_list, desc="Embedding"):
    """Embed a list of uint8 HxW numpy arrays. Returns (N, D) float32."""
    embeddings = []
    for patch in tqdm(patch_list, desc=desc):
        img = Image.fromarray(patch)
        x   = preprocess(img).unsqueeze(0).to(DEVICE)
        with torch.no_grad():
            feat = model(x)
        embeddings.append(feat.cpu().numpy().squeeze())
    return np.array(embeddings, dtype=np.float32)

# ── Embed HiRISE patches (56) ─────────────────────────────────────────────────
with open('./hirise_patches.pkl', 'rb') as f:
    hirise_records = pickle.load(f)

hirise_patches = [r['hirise_patch'] for r in hirise_records]
hirise_fnames  = [r['navcam_fname'] for r in hirise_records]  # paired NAVCAM fname
hirise_embs    = embed_patches(hirise_patches, desc="HiRISE")
print(f"HiRISE embeddings: {hirise_embs.shape}")

# ── Embed NAVCAM patches (50,400) ─────────────────────────────────────────────
with open('./navcam_patch_scores_horizon.pkl', 'rb') as f:
    navcam_records = pickle.load(f)

navcam_patches = [np.array(r['patch']) for r in navcam_records]
navcam_embs    = embed_patches(navcam_patches, desc="NAVCAM")
print(f"NAVCAM embeddings: {navcam_embs.shape}")

# ── Save both ─────────────────────────────────────────────────────────────────
np.save('./hirise_embs.npy',  hirise_embs)
np.save('./navcam_embs.npy',  navcam_embs)
print("Saved embeddings to disk.")

