    axes[0].imshow(chip, cmap='gray')
    axes[0].plot(chip_size//2, chip_size//2, 'r+', markersize=15, markeredgewidth=2)
    axes[0].set_title(f'HiRISE orbital\nSol {sol_str}\n{chip_size*0.25:.0f}m × {chip_size*0.25:.0f}m', fontsize=9)
    axes[0].axis('off')

    for i, (name, img) in enumerate(loaded):
        axes[i+1].imshow(img, cmap='gray')
        axes[i+1].set_title(f'NavCam {name.split("_")[2]}\nSol {sol_str}', fontsize=9)
        axes[i+1].axis('off')

    plt.suptitle(f'Sol {sol_str} — HiRISE (orbital) vs NavCam (ground)', fontsize=12)
    plt.tight_layout()
    plt.show()

