from tqdm import tqdm
import torch
from PIL import Image
import torchvision.transforms as T

# ── Load DINOv2 once ──────────────────────────────────────────────────────
model = torch.hub.load('facebookresearch/dinov2', 'dinov2_vits14')
model.eval().to('cuda')

transform = T.Compose([
    T.Resize((224, 224)),
    T.ToTensor(),
    T.Normalize(mean=[0.485, 0.456, 0.406], std=[0.229, 0.224, 0.225]),
])

def embed_images_batch(paths, batch_size=32):
    """Embed a list of image paths in batches — much faster."""
    embeddings = {}

    # Process in batches
    for i in tqdm(range(0, len(paths), batch_size), desc="Embedding"):
        batch_paths = paths[i:i+batch_size]
        tensors = []
        valid_paths = []

        for p in batch_paths:
            img = cv2.imread(p)
            if img is None:
                continue
            img_rgb = cv2.cvtColor(img, cv2.COLOR_BGR2RGB)
            tensor = transform(Image.fromarray(img_rgb))
            tensors.append(tensor)
            valid_paths.append(p)

        if not tensors:
            continue

        batch = torch.stack(tensors).to('cuda')
        with torch.no_grad():
            feats = model(batch).cpu().numpy()

        for path, feat in zip(valid_paths, feats):
            embeddings[path] = feat

    return embeddings

# ── Get unique NavCam image paths only ───────────────────────────────────
unique_images = df[
    df['image'].apply(lambda x: os.path.exists(os.path.join(NAVCAM_DIR, x)))
]['image'].unique()

navcam_paths = [os.path.join(NAVCAM_DIR, img) for img in unique_images]
print(f"Unique NavCam images to embed: {len(navcam_paths)}")

# ── Embed ─────────────────────────────────────────────────────────────────
navcam_embeddings = embed_images_batch(navcam_paths, batch_size=32)
print(f"Done: {len(navcam_embeddings)} embeddings")

# Run right after embed_images_batch finishes
import pickle
with open('/content/drive/MyDrive/Spring25/navcam_embeddings.pkl', 'wb') as f:
    pickle.dump(navcam_embeddings, f)
print("Embeddings saved to Drive ✓")

# ── HiRISE patch embedding ────────────────────────────────────────────────
# records already has 'patch' (PIL images) for HiRISE
hirise_records = [r for r in records if 'patch' in r]

hirise_pil_patches = [r['patch'] for r in hirise_records]
hirise_rp = np.array([r['rp'] for r in hirise_records])
hirise_hp = np.array([r['hp'] for r in hirise_records])
hirise_tp = np.array([r['tp'] for r in hirise_records])

print(f"HiRISE patches to embed: {len(hirise_pil_patches)}")

def embed_patches(pil_list, batch_size=64):
    """Embed a list of PIL patches."""
    all_feats = []
    for i in tqdm(range(0, len(pil_list), batch_size), desc="Embedding patches"):
        batch = pil_list[i:i+batch_size]
        tensors = torch.stack([transform(p.convert('RGB')) for p in batch]).to('cuda')
        with torch.no_grad():
            feats = model(tensors).cpu().numpy()
        all_feats.append(feats)
    return np.vstack(all_feats)

hirise_embs = embed_patches(hirise_pil_patches)
hirise_embs_norm = hirise_embs / (np.linalg.norm(hirise_embs, axis=1, keepdims=True) + 1e-8)
print(f"HiRISE embeddings: {hirise_embs_norm.shape}")

# Save immediately
with open('/content/drive/MyDrive/Spring25/hirise_embeddings.pkl', 'wb') as f:
    pickle.dump({'embs': hirise_embs_norm, 'rp': hirise_rp, 'hp': hirise_hp, 'tp': hirise_tp}, f)
print("HiRISE embeddings saved ✓")

# ── NavCam patch embeddings (from full images, same grid as scoring) ──────
navcam_patch_embs = []
navcam_patch_meta = []  # track image, cx, cy, rp, hp, tp

img_to_records = {}
for r in records:
    img_to_records.setdefault(r['image'], []).append(r)

for img_name, path in tqdm(zip(unique_images, navcam_paths),
                            total=len(navcam_paths), desc="NavCam patches"):
    img = cv2.imread(path)
    if img is None:
        continue
    img_rgb = cv2.cvtColor(img, cv2.COLOR_BGR2RGB)
    img_pil = Image.fromarray(img_rgb)

    recs = img_to_records.get(img_name, [])
    if not recs:
        continue

    # Embed all patches for this image in one batch
    patches = []
    for r in recs:
        cx, cy = r['cx'], r['cy']
        half = PATCH_SIZE // 2
        patch = img_pil.crop((cx-half, cy-half, cx+half, cy+half)).convert('RGB')
        patches.append(transform(patch))

    tensors = torch.stack(patches).to('cuda')
    with torch.no_grad():
        feats = model(tensors).cpu().numpy()

    for r, feat in zip(recs, feats):
        navcam_patch_embs.append(feat)
        navcam_patch_meta.append({'image': r['image'], 'cx': r['cx'], 'cy': r['cy'],
                                   'rp': r['rp'], 'hp': r['hp'], 'tp': r['tp']})

navcam_embs = np.vstack(navcam_patch_embs)
navcam_embs_norm = navcam_embs / (np.linalg.norm(navcam_embs, axis=1, keepdims=True) + 1e-8)
print(f"NavCam patch embeddings: {navcam_embs_norm.shape}")

# Save immediately
with open('/content/drive/MyDrive/Spring25/navcam_patch_embeddings.pkl', 'wb') as f:
    pickle.dump({'embs': navcam_embs_norm, 'meta': navcam_patch_meta}, f)
print("NavCam patch embeddings saved ✓")

from sklearn.metrics import roc_auc_score
from scipy.stats import pearsonr

# ── Cosine similarity matrix (HiRISE queries vs NavCam patches) ───────────
# This is large (137k x 137k) — do it in chunks to avoid OOM
print("Computing similarity matrix in chunks...")

TOP_K = 5
chunk_size = 1000
best_scores = np.zeros(len(hirise_embs_norm))

for i in tqdm(range(0, len(hirise_embs_norm), chunk_size), desc="Retrieval"):
    chunk = hirise_embs_norm[i:i+chunk_size]
    sim = chunk @ navcam_embs_norm.T  # (chunk, 137196)
    best_scores[i:i+chunk_size] = np.sort(sim, axis=1)[:, -TOP_K:][:, -1]

print(f"Best scores: min={best_scores.min():.3f}, max={best_scores.max():.3f}")

# ── Binary retrieval success label ────────────────────────────────────────
retrieval_success = (best_scores > np.median(best_scores)).astype(int)

# ── AUC ───────────────────────────────────────────────────────────────────
auc_tp = roc_auc_score(retrieval_success, hirise_tp)
auc_rp = roc_auc_score(retrieval_success, hirise_rp)
auc_hp = roc_auc_score(retrieval_success, hirise_hp)

print(f"\nAUC — T(p) combined : {auc_tp:.3f}")
print(f"AUC — R(p) stability: {auc_rp:.3f}")
print(f"AUC — H(p) entropy  : {auc_hp:.3f}")

# ── Pearson correlation ───────────────────────────────────────────────────
r_tp, p_tp = pearsonr(hirise_tp, best_scores)
r_rp, p_rp = pearsonr(hirise_rp, best_scores)
r_hp, p_hp = pearsonr(hirise_hp, best_scores)

print(f"\nr(T(p), retrieval) = {r_tp:.3f}  p={p_tp:.4f}")
print(f"r(R(p), retrieval) = {r_rp:.3f}  p={p_rp:.4f}")
print(f"r(H(p), retrieval) = {r_hp:.3f}  p={p_hp:.4f}")

# Save results
with open('/content/drive/MyDrive/Spring25/retrieval_results.pkl', 'wb') as f:
    pickle.dump({
        'best_scores': best_scores,
        'retrieval_success': retrieval_success,
        'auc_tp': auc_tp, 'auc_rp': auc_rp, 'auc_hp': auc_hp
    }, f)
print("\nResults saved ✓")

