def embed_patches(pil_list, batch_size=64):
    all_feats = []
    for i in tqdm(range(0, len(pil_list), batch_size), desc="Embedding"):
        batch = pil_list[i:i+batch_size]
        tensors = torch.stack([transform(p.convert('RGB')) for p in batch]).to('cuda')
        with torch.no_grad():
            feats = model(tensors).cpu().numpy()
        all_feats.append(feats)
    return np.vstack(all_feats)

print("DINOv2 loaded ✓")

PATCH_SIZE = 64
STRIDE = 32
half = PATCH_SIZE // 2
hirise_patches_pil = []
hirise_centres = []

with rasterio.open(HIRISE_PATH) as src:
    H, W = src.height, src.width
    STRIP_HEIGHT = 1000

    for row_off in tqdm(range(0, H, STRIP_HEIGHT), desc="Reading + extracting"):
        actual_height = min(STRIP_HEIGHT, H - row_off)
        window = Window(0, row_off, W, actual_height)
        strip = src.read(1, window=window).astype(np.float32) / 65535.0

        for cy_local in range(half, actual_height - half, STRIDE):
            cy_global = row_off + cy_local
            for cx in range(half, W - half, STRIDE):
                patch = strip[cy_local-half:cy_local+half, cx-half:cx+half]
                if patch.shape != (PATCH_SIZE, PATCH_SIZE):
                    continue
                patch_uint8 = (patch * 255).astype(np.uint8)
                pil = Image.fromarray(patch_uint8).convert('RGB')
                hirise_patches_pil.append(pil)
                hirise_centres.append((cx, cy_global))

        del strip

print(f"HiRISE patches extracted: {len(hirise_patches_pil)}")

