# ── Dataset: paired HiRISE chip + NavCam patch, weighted by T(p) ──────────
class PairedTerrainDataset(Dataset):
    def __init__(self, df, sol_positions, records_by_image, transform):
        self.pairs = []
        self.transform = transform

        # Build lookup: image -> patches with PIL
        # Only use horizon-filtered images that have position data
        overlap = set(df['sol'].unique()) & set(sol_positions['sol_str'].unique())

        for sol_str in sorted(overlap):
            pos_row = sol_positions[sol_positions['sol_str'] == sol_str]
            if pos_row.empty:
                continue
            x_m = pos_row.iloc[0]['x_m']
            y_m = pos_row.iloc[0]['y_m']

            # Get HiRISE chip for this sol
            try:
                chip = get_hirise_chip(x_m, y_m, chip_size=256)
                if chip is None or chip.max() == 0:
                    continue
            except:
                continue

            # Get NavCam patches for this sol from records
            sol_recs = [r for r in records if r['image'].split('_')[1].replace('sol','') ==
                       str(int(sol_str))]
            if not sol_recs:
                # try zero-padded
                sol_recs = [r for r in records if f"sol{sol_str}" in r['image']]
            if not sol_recs:
                continue

            # Extract patches from HiRISE chip
            chip_norm = chip.astype(np.float32) / (chip.max() + 1e-8)
            H, W = chip_norm.shape
            half = 32  # 64px patch

            for cy in range(half, H - half, 32):
                for cx in range(half, W - half, 32):
                    orbital_patch = chip_norm[cy-half:cy+half, cx-half:cx+half]
                    orbital_pil = Image.fromarray(
                        (orbital_patch * 255).astype(np.uint8)
                    ).convert('RGB')

                    # Pair with a random NavCam patch from same sol
                    rec = sol_recs[np.random.randint(len(sol_recs))]

                    self.pairs.append({
                        'orbital': orbital_pil,
                        'ground': rec['patch'],
                        'tp': rec['tp']
                    })

        print(f"Dataset: {len(self.pairs)} orbital-ground pairs from {len(overlap)} sols")

    def __len__(self):
        return len(self.pairs)

    def __getitem__(self, idx):
        pair = self.pairs[idx]
        orbital = self.transform(pair['orbital'].convert('RGB'))
        ground  = self.transform(pair['ground'].convert('RGB'))
        tp      = torch.tensor(pair['tp'], dtype=torch.float32)
        return orbital, ground, tp


# ── T(p)-weighted InfoNCE loss ────────────────────────────────────────────
def weighted_infonce(orbital_embs, ground_embs, tp_weights, tau=0.07):
    """
    orbital_embs: (B, 384) normalized
    ground_embs:  (B, 384) normalized
    tp_weights:   (B,) normalized T(p) scores
    """
    sim = orbital_embs @ ground_embs.T / tau  # (B, B)
    labels = torch.arange(sim.size(0), device=sim.device)

    loss_per_sample = F.cross_entropy(sim, labels, reduction='none')

    # Normalize weights to mean=1
    w = tp_weights - tp_weights.min() + 0.1
    w = w / w.mean()

    return (loss_per_sample * w).mean()


