def get_hirise_chip(x_m, y_m, chip_size=256):
    with rasterio.open(HIRISE_PATH) as src:
        row, col = src.index(x_m, y_m)
        half = chip_size // 2
        col_off = max(0, min(col - half, src.width - chip_size))
        row_off = max(0, min(row - half, src.height - chip_size))
        window = Window(col_off, row_off, chip_size, chip_size)
        return src.read(1, window=window)

