def is_valid_patch(pil_patch):
    arr = np.array(pil_patch.convert('L')).astype(np.float32) / 255.0

    # Reject too dark or too bright
    if arr.mean() < 0.1 or arr.mean() > 0.9:
        return False

    # Reject low variance (featureless sky/sand)
    if arr.std() < 0.05:
        return False

    # Reject calibration target (bright spots on dark background)
    bright_frac = (arr > 0.85).mean()
    dark_frac   = (arr < 0.15).mean()
    if bright_frac > 0.05 and dark_frac > 0.3:
        return False

    # Reject patches dominated by sky (uniform bright top half)
    top_half = arr[:32, :]
    if top_half.mean() > 0.7 and top_half.std() < 0.05:
        return False

    return True

# ── Rebuild dataset with filter ───────────────────────────────────────────
class PairedTerrainDataset(Dataset):
    def __init__(self, df, sol_positions, records, transform):
        self.pairs = []
        self.transform = transform

        overlap = set(df['sol'].unique()) & set(sol_positions['sol_str'].unique())

        sol_to_recs = {}
        for r in records:
            sol = r['image'].split('sol')[1].split('_')[0]
            sol_to_recs.setdefault(sol, []).append(r)

        # Pre-filter records by patch quality
        sol_to_valid_recs = {}
        for sol, recs in sol_to_recs.items():
            valid = [r for r in recs if is_valid_patch(r['patch'])]
            if valid:
                sol_to_valid_recs[sol] = valid

        print(f"Valid patches after filtering:")
        total_before = sum(len(v) for v in sol_to_recs.values())
        total_after  = sum(len(v) for v in sol_to_valid_recs.values())
        print(f"  Before: {total_before}  After: {total_after}  "
              f"({100*total_after/total_before:.1f}% kept)")

        for sol_str in tqdm(sorted(overlap), desc="Building pairs"):
            pos_row = sol_positions[sol_positions['sol_str'] == sol_str]
            if pos_row.empty:
                continue

            sol_recs = sol_to_valid_recs.get(sol_str, [])
            if not sol_recs:
                print(f"  Sol {sol_str}: no valid patches after filter")
                continue

            try:
                chip = get_hirise_chip(pos_row.iloc[0]['x_m'],
                                       pos_row.iloc[0]['y_m'],
                                       chip_size=256)
                if chip is None or chip.max() == 0:
                    continue
            except Exception as e:
                print(f"  Sol {sol_str} chip error: {e}")
                continue

            chip_norm = chip.astype(np.float32) / (chip.max() + 1e-8)
            H, W = chip_norm.shape
            half = 32

            for cy in range(half, H - half, 32):
                for cx in range(half, W - half, 32):
                    orbital_patch = chip_norm[cy-half:cy+half, cx-half:cx+half]
                    orbital_pil = Image.fromarray(
                        (orbital_patch * 255).astype(np.uint8)
                    ).convert('RGB')
                    rec = sol_recs[np.random.randint(len(sol_recs))]
                    self.pairs.append({
                        'orbital': orbital_pil,
                        'ground':  rec['patch'],
                        'tp':      rec['tp']
                    })

        print(f"\nDataset: {len(self.pairs)} pairs from {len(overlap)} sols")

    def __len__(self):
        return len(self.pairs)

    def __getitem__(self, idx):
        pair = self.pairs[idx]
        orbital = self.transform(pair['orbital'].convert('RGB'))
        ground  = self.transform(pair['ground'].convert('RGB'))
        tp      = torch.tensor(pair['tp'], dtype=torch.float32)
        return orbital, ground, tp

# ── Rebuild ───────────────────────────────────────────────────────────────
dataset = PairedTerrainDataset(df, sol_positions, records, transform_train)
loader  = DataLoader(dataset, batch_size=16, shuffle=True, num_workers=2)
print(f"Batches per epoch: {len(loader)}")

import random

def is_valid_patch(pil_patch):
    arr = np.array(pil_patch.convert('L')).astype(np.float32) / 255.0
    if arr.mean() < 0.1 or arr.mean() > 0.9:
        return False
    if arr.std() < 0.08:
        return False
    bright_frac = (arr > 0.85).mean()
    dark_frac   = (arr < 0.15).mean()
    if bright_frac > 0.05 and dark_frac > 0.3:
        return False
    top_half = arr[:32, :]
    if top_half.mean() > 0.7 and top_half.std() < 0.05:
        return False
    grad_x = np.abs(np.diff(arr, axis=1)).mean()
    grad_y = np.abs(np.diff(arr, axis=0)).mean()
    if (grad_x + grad_y) / 2 > 0.08:
        return False
    return True

valid_records   = [r for r in records if is_valid_patch(r['patch'])]
rejected        = [r for r in records if not is_valid_patch(r['patch'])]
print(f"Passed: {len(valid_records)}  Rejected: {len(rejected)}  ({100*len(valid_records)/len(records):.1f}% kept)")

# ── Visual inspection ─────────────────────────────────────────────────────
fig, axes = plt.subplots(4, 10, figsize=(20, 9))
fig.suptitle('Random sample — PASSED filter', fontsize=12)
for i, rec in enumerate(random.sample(valid_records, min(40, len(valid_records)))):
    axes[i//10, i%10].imshow(rec['patch'])
    axes[i//10, i%10].axis('off')
plt.tight_layout()
plt.show()

fig2, axes2 = plt.subplots(4, 10, figsize=(20, 9))
fig2.suptitle('Random sample — REJECTED by filter', fontsize=12)
for i, rec in enumerate(random.sample(rejected, min(40, len(rejected)))):
    axes2[i//10, i%10].imshow(rec['patch'])
    axes2[i//10, i%10].axis('off')
plt.tight_layout()
plt.show()

