for batch_num in range(n_batches):
    start = batch_num * BATCH_SIZE
    end   = min(start + BATCH_SIZE, len(valid_records))
    batch = valid_records[start:end]
    if not batch:
        break

    fig, axes = plt.subplots(4, 10, figsize=(20, 10))
    fig.suptitle(f'Batch {batch_num+1}/{n_batches} — indices {start}–{end-1}', fontsize=12)
    for i, rec in enumerate(batch):
        row, col = i // 10, i % 10
        axes[row, col].imshow(rec['patch'])
        axes[row, col].set_title(str(start + i), fontsize=9, color='red')
        axes[row, col].axis('off')
    for j in range(len(batch), 40):
        axes[j//10, j%10].axis('off')
