from torch.utils.data import Dataset, DataLoader
import torch.nn.functional as F
import torchvision.transforms as T

transform_train = T.Compose([
    T.RandomHorizontalFlip(),
    T.RandomVerticalFlip(),
    T.ColorJitter(brightness=0.2, contrast=0.2),
    T.Resize((224, 224)),
    T.ToTensor(),
    T.Normalize(mean=[0.485, 0.456, 0.406], std=[0.229, 0.224, 0.225]),
])

def weighted_infonce(orbital_embs, ground_embs, tp_weights, tau=0.07):
    sim = orbital_embs @ ground_embs.T / tau
    labels = torch.arange(sim.size(0), device=sim.device)
    loss_per_sample = F.cross_entropy(sim, labels, reduction='none')
    w = tp_weights - tp_weights.min() + 0.1
    w = w / w.mean()
    return (loss_per_sample * w).mean()

print("Imports ✓")

# ── Rebuild dataset with clean records ────────────────────────────────────
class PairedTerrainDataset(Dataset):
    def __init__(self, clean_records, sol_positions, transform):
        self.pairs = []
        self.transform = transform

        # Build sol -> records lookup from clean records
        sol_to_recs = {}
        for r in clean_records:
            sol = r['image'].split('sol')[1].split('_')[0]
            sol_to_recs.setdefault(sol, []).append(r)

        overlap = set(sol_to_recs.keys()) & set(sol_positions['sol_str'].unique())

        for sol_str in tqdm(sorted(overlap), desc="Building pairs"):
            pos_row = sol_positions[sol_positions['sol_str'] == sol_str]
            if pos_row.empty:
                continue
            sol_recs = sol_to_recs.get(sol_str, [])
            if not sol_recs:
                continue
            try:
                chip = get_hirise_chip(pos_row.iloc[0]['x_m'],
                                       pos_row.iloc[0]['y_m'],
                                       chip_size=256)
                if chip is None or chip.max() == 0:
                    continue
            except:
                continue

            chip_norm = chip.astype(np.float32) / (chip.max() + 1e-8)
            H, W = chip_norm.shape
            half = 32
            for cy in range(half, H - half, 32):
                for cx in range(half, W - half, 32):
                    orbital_patch = chip_norm[cy-half:cy+half, cx-half:cx+half]
                    orbital_pil = Image.fromarray(
                        (orbital_patch * 255).astype(np.uint8)
                    ).convert('RGB')
                    rec = sol_recs[np.random.randint(len(sol_recs))]
                    self.pairs.append({
                        'orbital': orbital_pil,
                        'ground':  rec['patch'],
                        'tp':      rec['tp']
                    })

        print(f"Dataset: {len(self.pairs)} pairs from {len(overlap)} sols")

    def __len__(self): return len(self.pairs)
    def __getitem__(self, idx):
        pair = self.pairs[idx]
        return (self.transform(pair['orbital'].convert('RGB')),
                self.transform(pair['ground'].convert('RGB')),
                torch.tensor(pair['tp'], dtype=torch.float32))

dataset = PairedTerrainDataset(valid_records_clean, sol_positions, transform_train)
loader  = DataLoader(dataset, batch_size=16, shuffle=True, num_workers=2)
print(f"Batches per epoch: {len(loader)}")

# ── Reset model + optimizer ───────────────────────────────────────────────
model = torch.hub.load('facebookresearch/dinov2', 'dinov2_vits14')
model.eval().to('cuda')

for name, param in model.named_parameters():
    param.requires_grad = False
for name, param in model.named_parameters():
    if 'blocks.11' in name or 'norm' in name:
        param.requires_grad = True

optimizer = torch.optim.AdamW(
    [p for p in model.parameters() if p.requires_grad],
    lr=1e-5, weight_decay=0.01
)

# ── Train ─────────────────────────────────────────────────────────────────
EPOCHS = 30
model.train()
loss_history = []

for epoch in range(EPOCHS):
    epoch_loss, n_batches = 0, 0
    for orbital, ground, tp in tqdm(loader, desc=f"Epoch {epoch+1}/{EPOCHS}", leave=False):
        orbital, ground, tp = orbital.to('cuda'), ground.to('cuda'), tp.to('cuda')
        orb_emb = F.normalize(model(orbital), dim=-1)
        gnd_emb = F.normalize(model(ground),  dim=-1)
        loss = weighted_infonce(orb_emb, gnd_emb, tp)
        optimizer.zero_grad()
        loss.backward()
        torch.nn.utils.clip_grad_norm_(model.parameters(), 1.0)
        optimizer.step()
        epoch_loss += loss.item()
        n_batches  += 1
    avg = epoch_loss / n_batches
    loss_history.append(avg)
    print(f"Epoch {epoch+1:02d}/{EPOCHS}  loss={avg:.4f}")

# ── Save immediately ───────────────────────────────────────────────────────
torch.save(model.state_dict(),
           '/content/drive/MyDrive/NASA_Mars_Curiosity/dinov2_finetuned_v4.pth')
print("Saved v4 to Drive ✓")

plt.figure(figsize=(8, 4))
plt.plot(range(1, EPOCHS+1), loss_history, 'o-', color='steelblue')
plt.xlabel('Epoch'); plt.ylabel('Loss')
plt.title('Fine-tuning Loss — v4 (manually cleaned patches)')
plt.grid(alpha=0.3); plt.tight_layout(); plt.show()

model.eval()
all_orb_embs = []
all_gnd_embs = []
all_tp = []

with torch.no_grad():
    for orbital, ground, tp in tqdm(loader, desc="Evaluating"):
        orb_emb = F.normalize(model(orbital.to('cuda')), dim=-1)
        gnd_emb = F.normalize(model(ground.to('cuda')),  dim=-1)
        all_orb_embs.append(orb_emb.cpu())
        all_gnd_embs.append(gnd_emb.cpu())
        all_tp.extend(tp.numpy().tolist())

all_orb = torch.cat(all_orb_embs)
all_gnd = torch.cat(all_gnd_embs)
all_tp  = np.array(all_tp)

same_pair   = (all_orb * all_gnd).sum(dim=-1).numpy()
idx         = torch.randperm(len(all_gnd))
random_pair = (all_orb * all_gnd[idx]).sum(dim=-1).numpy()

print(f"Same-pair  : {same_pair.mean():.3f} ± {same_pair.std():.3f}  (v3: 0.174)")
print(f"Random-pair: {random_pair.mean():.3f} ± {random_pair.std():.3f}  (v3: 0.008)")
print(f"Delta      : {same_pair.mean() - random_pair.mean():.3f}          (v3: 0.165)")

r, p = spearmanr(all_tp, same_pair)
print(f"Spearman r(T(p), sim): {r:.3f}  p={p:.4f}  (v3: 0.030)")

