"""## 7 — DINOv2 Embedding

Embed all filtered NAVCAM patches with DINOv2 ViT-S/14.
These embeddings are used as the retrieval space: given a HiRISE orbital patch,
we query against the NAVCAM patch bank and ask whether T(p) predicts success.

"""

device = 'cuda' if torch.cuda.is_available() else 'cpu'
print(f"Device: {device}")

dino = torch.hub.load('facebookresearch/dinov2', 'dinov2_vits14', pretrained=True)
dino = dino.to(device).eval()

dino_tfm = T.Compose([
    T.Resize((224, 224)),
    T.ToTensor(),
    T.Normalize(mean=[0.485, 0.456, 0.406],
                std =[0.229, 0.224, 0.225]),
])

@torch.no_grad()
def embed_patches(pil_list, batch_size=64):
    all_emb = []
    for i in range(0, len(pil_list), batch_size):
        batch = torch.stack([dino_tfm(p) for p in pil_list[i:i+batch_size]]).to(device)
        emb   = dino(batch).cpu().numpy()
        all_emb.append(emb)
    return np.vstack(all_emb)

# Embed all NAVCAM patches
print(f"Embedding {len(records)} NAVCAM patches …")
navcam_patches_pil = [r['patch'] for r in records]
navcam_embs        = embed_patches(navcam_patches_pil)
print(f"NAVCAM embeddings: {navcam_embs.shape}")

# Normalise for cosine retrieval
navcam_embs_norm = navcam_embs / (np.linalg.norm(navcam_embs, axis=1, keepdims=True) + 1e-8)

"""## 8 — HiRISE Query Patches

Extract dense grid patches from the HiRISE orbital image.
These are the *queries*: for each HiRISE patch we ask whether the
highest-T(p) NAVCAM patches are also the most retrievable.

"""

HIRISE_PATH = "/content/drive/MyDrive/NASA_Mars_Curiosity/HiRISE/gale_crater_patch.jpg"

hirise_bgr  = cv2.imread(HIRISE_PATH)
hirise_gray = cv2.cvtColor(hirise_bgr, cv2.COLOR_BGR2GRAY)
hirise_pil  = Image.fromarray(cv2.cvtColor(hirise_bgr, cv2.COLOR_BGR2RGB))

hirise_gray_patches, hirise_pil_patches, hirise_centres = extract_grid_patches(
    hirise_gray, hirise_pil
)
print(f"HiRISE: {len(hirise_centres)} query patches")

# ── Pass 1: raw scores ────────────────────────────────────────────────────
print("Scoring HiRISE patches …")
raw_scores = [(compute_rp(pg), compute_hp(pg))
              for pg in tqdm(hirise_gray_patches, desc="R(p)/H(p) HiRISE")]

hirise_rp = np.array([s[0] for s in raw_scores])
hirise_hp = np.array([s[1] for s in raw_scores])

# ── Pass 2: normalize using HiRISE population stats ──────────────────────
rp_std = hirise_rp.std()
hp_std = hirise_hp.std()
hirise_tp = np.array([
    compute_tp(rp, hp, rp_std, hp_std, alpha=ALPHA, beta=BETA)
    for rp, hp in zip(hirise_rp, hirise_hp)
])

print("Embedding HiRISE patches …")
hirise_embs      = embed_patches(hirise_pil_patches)
hirise_embs_norm = hirise_embs / (np.linalg.norm(hirise_embs, axis=1, keepdims=True) + 1e-8)
print(f"HiRISE embeddings: {hirise_embs_norm.shape}")

"""## 9 — Top-k Retrieval & AUC Evaluation

For each HiRISE patch we retrieve the top-k NAVCAM patches by cosine
similarity and record whether the match score is above a threshold
(proxy for ground truth without explicit labels).

Then we test: **does T(p) predict retrieval success?**

"""

TOP_K = 5

# Cosine similarity: (n_hirise, n_navcam)
sim_matrix = hirise_embs_norm @ navcam_embs_norm.T   # shape (Q, N)

# For each HiRISE query: best cosine score in top-k
best_scores      = np.sort(sim_matrix, axis=1)[:, -TOP_K:][:, -1]   # top-1 score
retrieval_success = (best_scores > best_scores.median()).astype(int)   # binary label

# AUC: does T(p) predict top-1 similarity?
from sklearn.metrics import roc_auc_score
auc_tp = roc_auc_score(retrieval_success, hirise_tp)
auc_rp = roc_auc_score(retrieval_success, hirise_rp)
auc_hp = roc_auc_score(retrieval_success, hirise_hp)

print(f"AUC — T(p) combined : {auc_tp:.3f}")
print(f"AUC — R(p) stability: {auc_rp:.3f}")
print(f"AUC — H(p) entropy  : {auc_hp:.3f}")
print()

# Correlation with best retrieval score
from scipy.stats import pearsonr
r_tp, p_tp = pearsonr(hirise_tp, best_scores)
r_rp, p_rp = pearsonr(hirise_rp, best_scores)
r_hp, p_hp = pearsonr(hirise_hp, best_scores)
print(f"r(T(p), retrieval) = {r_tp:.3f}  p={p_tp:.4f}")
print(f"r(R(p), retrieval) = {r_rp:.3f}  p={p_rp:.4f}")
print(f"r(H(p), retrieval) = {r_hp:.3f}  p={p_hp:.4f}")

"""## 10 — T(p) Heatmap over HiRISE Image"""

H_hi, W_hi = hirise_gray.shape
half = PATCH_SIZE // 2
tp_map = np.full((H_hi, W_hi), np.nan)
for (cx, cy), tp in zip(hirise_centres, hirise_tp):
    tp_map[cy-half:cy+half, cx-half:cx+half] = tp

tp_smooth = gaussian_filter(np.nan_to_num(tp_map), sigma=8)

fig, axes = plt.subplots(1, 3, figsize=(18, 6))

axes[0].imshow(cv2.cvtColor(hirise_bgr, cv2.COLOR_BGR2RGB))
axes[0].set_title("HiRISE orbital image"); axes[0].axis('off')

im1 = axes[1].imshow(tp_smooth, cmap='RdYlGn', vmin=0, vmax=tp_smooth.max())
axes[1].set_title("T(p) heatmap\n(green = reliable, red = unreliable)")
axes[1].axis('off')
plt.colorbar(im1, ax=axes[1], fraction=0.046, pad=0.04)

# Overlay top/bottom 10% on image
rgb_overlay = cv2.cvtColor(hirise_bgr, cv2.COLOR_BGR2RGB).copy()
top_thresh = np.nanpercentile(tp_smooth, 90)
bot_thresh = np.nanpercentile(tp_smooth, 10)
for (cx, cy), tp in zip(hirise_centres, hirise_tp):
    color = (0, 200, 0) if tp >= top_thresh else ((200, 0, 0) if tp <= bot_thresh else None)
    if color:
        cv2.circle(rgb_overlay, (cx, cy), PATCH_SIZE//4, color, 2)
axes[2].imshow(rgb_overlay)
axes[2].set_title("Top 10% T(p) = green  |  Bottom 10% = red"); axes[2].axis('off')

plt.suptitle("HiRISE Landmark Reliability Map", fontsize=13)
plt.tight_layout(); plt.show()

"""## 11 — Patch Gallery: High vs Low T(p)"""

df_hi = pd.DataFrame({
    'tp': hirise_tp, 'rp': hirise_rp, 'hp': hirise_hp,
    'idx': range(len(hirise_tp))
})
top10 = df_hi.nlargest(10, 'tp')
bot10 = df_hi.nsmallest(10, 'tp')

fig, axes = plt.subplots(2, 10, figsize=(20, 5))
fig.suptitle("High T(p) (top row) vs Low T(p) (bottom row) — HiRISE patches", fontsize=11)

for col, (_, row) in enumerate(top10.iterrows()):
    i = int(row['idx'])
    axes[0, col].imshow(hirise_pil_patches[i], cmap='gray')
    axes[0, col].set_title(f"T={row['tp']:.2f}\nR={row['rp']:.2f}", fontsize=7)
    axes[0, col].axis('off')

for col, (_, row) in enumerate(bot10.iterrows()):
    i = int(row['idx'])
    axes[1, col].imshow(hirise_pil_patches[i], cmap='gray')
    axes[1, col].set_title(f"T={row['tp']:.2f}\nR={row['rp']:.2f}", fontsize=7)
    axes[1, col].axis('off')

plt.tight_layout(); plt.show()

"""## 12 — Precision–Coverage Tradeoff

If we only use patches above a T(p) threshold, what fraction of the
image are we covering, and what precision do we get on retrieval?
This is the operationally relevant curve: a mission engineer can choose
the coverage they need and read off the expected reliability.

"""

thresholds  = np.linspace(hirise_tp.min(), hirise_tp.max(), 50)
precisions  = []
coverages   = []

for thresh in thresholds:
    mask     = hirise_tp >= thresh
    coverage = mask.mean()
    if mask.sum() == 0:
        precisions.append(np.nan)
    else:
        prec = retrieval_success[mask].mean()
        precisions.append(prec)
    coverages.append(coverage)

fig, ax = plt.subplots(figsize=(8, 5))
ax.plot(coverages, precisions, 'o-', color='steelblue', markersize=4)
ax.set_xlabel("Coverage (fraction of patches retained)", fontsize=12)
ax.set_ylabel("Precision (retrieval success rate)", fontsize=12)
ax.set_title("T(p) Precision–Coverage Tradeoff\n"
             "Selecting high-T(p) landmarks trades coverage for reliability", fontsize=11)
ax.axhline(0.5, color='gray', linestyle='--', alpha=0.5, label='random baseline')
ax.legend(); ax.grid(alpha=0.3)
plt.tight_layout(); plt.show()